1 mark for:
 •   Calculate() function header (and end where appropriate)
 •   Looping until the stack is empty
 •   Calling Pop() repeatedly within loop and storing/using return value
 •   … working out if return value from Pop() call is an operator or a number / alternating between operator and number
 •   Select to determine if the operator is +, -, /, * or ^ and attempt the matching calculation
 •   … performing correct calculation using operator, number
 •   … updating total from previous loops and returning this final value
Example program code:
Java
public static Double Calculate(){
Double Total = Double.parseDouble(Pop());
String ReturnValue = "";
String LastOperator = "";
Boolean OperatorFlag = true;
Integer TheData = 0;
while(ReturnValue != "-1"){
    ReturnValue = Pop();
    if(OperatorFlag == false){
          TheData = Integer.parseInt(ReturnValue);
          if(LastOperator.compareTo("+")==0){
                 Total = Total + TheData;
          }else if(LastOperator.compareTo("-")==0){
                 Total = Total - TheData;
          }else if(LastOperator.compareTo("*")==0){
                 Total = Total * TheData;
          }else if(LastOperator.compareTo("/")==0){
                 Total = Total / TheData;
          }else if(LastOperator.compareTo("^")==0){
                 Total = Math.pow(Total, TheData);
          }
          OperatorFlag = true;
    }else{
          LastOperator = ReturnValue;
          OperatorFlag = false;
    }
}
return Total;
}
VB.NET
Function Calculate()
Dim Total As Integer = Pop()
Dim ReturnValue As String = ""
Dim LastOperator As String = ""
Dim OperatorFlag As Boolean = True
Dim TheData As Integer = 0
While (ReturnValue <> "-1")
ReturnValue = Pop()
Select Case OperatorFlag
     Case False
          TheData = ReturnValue
          Select Case LastOperator
              Case "+"
                   Total = Total + TheData
              Case "-"
                   Total = Total - TheData
              Case "*"
                   Total = Total * TheData
              Case "/"
                   Total = Total / TheData
              Case "^"
                   Total = Total ^ TheData
          End Select
          OperatorFlag = True
     Case Else
          LastOperator = ReturnValue
          OperatorFlag = False
End Select
End While
Return Total
End Function
Python
def Calculate():
global Stack
global TopOfStack
Total = Pop()
Total = int(Total)
Return = 0
LastOperator = ""
Operator = True
while(Return != "-1"):
Return = Pop()
if Operator == False:
     Data = int(Return)
     if LastOperator == "+":
          Total = Total + Data
     elif LastOperator == "-":
          Total = Total - Data
     elif LastOperator == "*":
          Total = Total * Data
     elif LastOperator == "/":
          Total = Total / Data
     elif LastOperator == "^":
          Total = Total ** Data
     Operator = True
else:
     LastOperator = Return
     Operator = False
return Total

